async function listChecklistItems(client, projectId, args) {
  const resolvedId = await resolveTaskId(client, projectId, args.task_id);
  const { data, error } = await client.from("checklist_items").select("id, title, completed, position, created_by, created_at").eq("task_id", resolvedId).order("position", { ascending: true });
  if (error) throw error;
  return data;
}
async function manageChecklistItems(client, projectId, userId, args) {
  const resolvedTaskId = await resolveTaskId(client, projectId, args.task_id);
  const results = {
    added: [],
    updated: [],
    deleted: []
  };
  let maxPosition = -1;
  if (args.add && args.add.length > 0) {
    const { data: existing } = await client.from("checklist_items").select("position").eq("task_id", resolvedTaskId).order("position", { ascending: false }).limit(1);
    maxPosition = existing?.[0]?.position ?? -1;
  }
  if (args.add && args.add.length > 0) {
    const rows = args.add.map((item, i) => ({
      task_id: resolvedTaskId,
      title: normalizeHtmlEntities(item.title),
      position: maxPosition + 1 + i,
      created_by: userId
    }));
    const { data, error } = await client.from("checklist_items").insert(rows).select();
    if (error) throw error;
    results.added = data ?? [];
  }
  if (args.update && args.update.length > 0) {
    for (const item of args.update) {
      const { id, ...updates } = item;
      const payload2 = {};
      if (updates.title !== void 0) payload2.title = normalizeHtmlEntities(updates.title);
      if (updates.completed !== void 0) payload2.completed = updates.completed;
      if (Object.keys(payload2).length === 0) continue;
      const { data, error } = await client.from("checklist_items").update(payload2).eq("id", id).eq("task_id", resolvedTaskId).select().single();
      if (error) throw error;
      results.updated.push(data);
    }
  }
  if (args.delete && args.delete.length > 0) {
    const { error } = await client.from("checklist_items").delete().in("id", args.delete).eq("task_id", resolvedTaskId);
    if (error) throw error;
    results.deleted = args.delete;
  }
  return results;
}

